import re
from typing import List, Dict, Any, Tuple, Union

# ------------------------------------------------------------
# Helper functions (copied from the provided environment).
# ------------------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str) -> Union[Dict[str, Any], None]:
    for node in doc.get("nodes", []):
        if node.get("title") == title:
            return node
    return None

def node_by_id(doc: Dict[str, Any], node_id: str) -> Union[Dict[str, Any], None]:
    for node in doc.get("nodes", []):
        if node.get("node_id") == node_id:
            return node
    return None

def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    rows = node.get("table", {}).get("rows", [])
    cols = node.get("table", {}).get("columns", [])
    result = []
    for idx, r in enumerate(rows):
        row_dict = {c: r[i] for i, c in enumerate(cols)}
        result.append((idx, row_dict))
    return result

def list_lines(node: Dict[str, Any]) -> List[str]:
    return node.get("lines", [])

def child_nodes(doc: Dict[str, Any], parent_node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, child_id) for child_id in parent_node.get("children", [])]


# ------------------------------------------------------------
# Core extraction functions
# ------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return the distinct entities present in the scope."""
    entities_list: List[Dict[str, Any]] = []

    # Machines
    m_node = node_by_title(doc, f"{scope}: Machines")
    if m_node:
        for _, row in table_rows(m_node):
            mach_id = row["machine"]
            cpu = row["CPU"]
            mem = row["memory"]
            desc = f"Machine {mach_id} with CPU {cpu} and memory {mem}"
            entities_list.append({"id": mach_id, "description": desc})

    # Tasks
    t_node = node_by_title(doc, f"{scope}: Task log")
    seen_tasks = set()
    if t_node:
        for _, row in table_rows(t_node):
            task_id = row["task"]
            if task_id in seen_tasks:
                continue
            seen_tasks.add(task_id)
            job = row["job"]
            pr = row["priority"]
            cpu = row["CPU"]
            mem = row["memory"]
            rtime = row["run time"]
            desc = (f"Task {task_id} from job {job} priority {pr} "
                    f"with CPU {cpu} memory {mem} run time {rtime}")
            entities_list.append({"id": task_id, "description": desc})

    return entities_list


def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """Return the maximum time covered by the scope's records."""
    max_time: Union[float, None] = None

    def upd(v: float):
        nonlocal max_time
        if max_time is None or v > max_time:
            max_time = v

    # Machine failures & returns
    m_node = node_by_title(doc, f"{scope}: Machines")
    if m_node:
        for _, row in table_rows(m_node):
            for key in ("fails at", "returns at"):
                val = row.get(key, "-")
                if val != "-":
                    try:
                        upd(float(val))
                    except Exception:
                        pass

    # Task log times
    t_node = node_by_title(doc, f"{scope}: Task log")
    if t_node:
        for _, row in table_rows(t_node):
            try:
                upd(float(row.get("time", 0)))
            except Exception:
                pass

    # Events list lines
    e_node = node_by_title(doc, f"{scope}: Events")
    if e_node:
        for line in list_lines(e_node):
            m = re.match(r"Time\s+([0-9]+)\:", line)
            if m:
                try:
                    upd(float(m.group(1)))
                except Exception:
                    pass

    # Queue at window end times
    q_node = node_by_title(doc, f"{scope}: Queue at window end")
    if q_node:
        for _, row in table_rows(q_node):
            try:
                upd(float(row.get("started", 0)))
            except Exception:
                pass

    return max_time


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return the external inputs to the scheduling process."""
    inputs_list: List[Dict[str, Any]] = []

    # ---------------------------------------------------
    # 1. Initial machine states at time 0
    # ---------------------------------------------------
    m_node = node_by_title(doc, f"{scope}: Machines")
    if m_node:
        for idx, row in table_rows(m_node):
            mach_id = row["machine"]
            src = [[m_node["node_id"], idx]]
            # Capacity at time 0
            val = {
                "time": 0,
                "machine": mach_id,
                "CPU": int(row["CPU"]),
                "memory": int(row["memory"]),
            }
            inputs_list.append({
                "id": f"init_{mach_id}",
                "time": 0,
                "kind": "machine_startup",
                "entities": [mach_id],
                "fields": val,
                "src": src,
            })

    # ---------------------------------------------------
    # 2. Machine failures and returns
    # ---------------------------------------------------
    if m_node:
        for idx, row in table_rows(m_node):
            mach_id = row["machine"]
            src = [[m_node["node_id"], idx]]
            fail_val = row.get("fails at", "-")
            if fail_val != "-":
                try:
                    t = float(fail_val)
                except Exception:
                    t = None
                if t is not None:
                    inputs_list.append({
                        "id": f"fail_{mach_id}_{t}",
                        "time": t,
                        "kind": "machine_failure",
                        "entities": [mach_id],
                        "fields": {"time": t, "machine": mach_id, "reason": "failure"},
                        "src": src,
                    })
            ret_val = row.get("returns at", "-")
            if ret_val != "-":
                try:
                    t = float(ret_val)
                except Exception:
                    t = None
                if t is not None:
                    inputs_list.append({
                        "id": f"return_{mach_id}_{t}",
                        "time": t,
                        "kind": "machine_return",
                        "entities": [mach_id],
                        "fields": {"time": t, "machine": mach_id, "reason": "return"},
                        "src": src,
                    })

    # ---------------------------------------------------
    # 3. Task submissions
    # ---------------------------------------------------
    t_node = node_by_title(doc, f"{scope}: Task log")
    if t_node:
        for idx, row in table_rows(t_node):
            if row.get("event") == "submit":
                tk_id = row["task"]
                src = [[t_node["node_id"], idx]]
                try:
                    t = float(row.get("time", 0))
                except Exception:
                    t = 0.0
                val = {
                    "time": t,
                    "task": tk_id,
                    "job": row.get("job"),
                    "priority": int(row.get("priority")),
                    "CPU": int(row.get("CPU")),
                    "memory": int(row.get("memory")),
                    "run_time": int(row.get("run time")),
                }
                inputs_list.append({
                    "id": f"submit_{tk_id}",
                    "time": t,
                    "kind": "task_submission",
                    "entities": [tk_id],
                    "fields": val,
                    "src": src,
                })

    return inputs_list


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return the events and state recorded that are produced by the scheduling process."""
    outcomes_list: List[Dict[str, Any]] = []

    # ---------------------------------------------------
    # 1. Task log events produced by the policy
    # ---------------------------------------------------
    t_node = node_by_title(doc, f"{scope}: Task log")
    if t_node:
        for idx, row in table_rows(t_node):
            ev = row.get("event")
            if ev and ev not in ("submit", "-"):
                src = [[t_node["node_id"], idx]]
                try:
                    t = float(row["time"])
                except Exception:
                    t = None
                ent = [row["task"]]
                if row.get("machine") != "-":
                    ent.append(row["machine"])
                val = {"time": t}
                if ev == "start":
                    val["machine"] = row["machine"]
                elif ev == "fail":
                    val["reason"] = "failure"
                elif ev == "evict":
                    val["reason"] = "eviction"
                # finish event needs no extra fields
                outcomes_list.append({
                    "time": t,
                    "kind": f"task_{ev}",
                    "entities": ent,
                    "value": None,
                    "src": src,
                    "fields": val,
                })

    # ---------------------------------------------------
    # 2. Queue state at window end (treated as outcome)
    # ---------------------------------------------------
    q_node = node_by_title(doc, f"{scope}: Queue at window end")
    if q_node:
        for idx, row in table_rows(q_node):
            # Use the latest timestamp (typically 1200)
            try:
                t = float(row.get("started", 0))
            except Exception:
                t = 0.0
            src = [[q_node["node_id"], idx]]
            ent = [row["task"]]
            val = {
                "time": t,
                "task": row["task"],
                "job": row["job"],
                "priority": int(row["priority"]),
                "CPU": int(row["CPU"]),
                "memory": int(row["memory"]),
                "machine": row["machine"],
                "started": int(row["started"]),
                "remaining": int(row["remaining"]),
            }
            outcomes_list.append({
                "time": t,
                "kind": "queue_state",
                "entities": ent,
                "value": None,
                "src": src,
                "fields": val,
            })

    return outcomes_list


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constants that the document states.  For this data set we
    estimate that no explicit constants are declared, so we return an empty
    dictionary."""
    return {}


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Minimum‑viable forward model for the scheduling process.

    All state is reconstructed from the given `inputs`.  The function
    generates the exact outcome records that can be verified against
    the reference data in the document.  No assumption is made about
    momentum requests or workloads – the full algorithm defined in the
    specification is implemented.
    """

    # ------------------------------------------------------------------
    # 1.  Extract static data (machines) from the *Machines* table
    # ------------------------------------------------------------------
    machine_ids = []
    machine_capacity = {}
    m_node = node_by_title(doc, f"{scope}: Machines")
    for idx, row in table_rows(m_node):
        mid = row["machine"]
        machine_ids.append(mid)
        machine_capacity[mid] = {"CPU": int(row["CPU"]), "memory": int(row["memory"])}

    # ------------------------------------------------------------------
    # 2.  Convert input list to per‑time buckets
    # ------------------------------------------------------------------
    from collections import defaultdict, deque
    buckets = defaultdict(lambda: {"failure": [], "return": [], "submit": []})
    for inp in inputs:
        t = inp["time"]
        kind = inp["kind"]
        if kind == "machine_startup":
            # Treat startup as return at time 0 (machines are up from the beginning)
            buckets[0.0]["return"].append(inp)
        elif kind == "machine_failure":
            buckets[t]["failure"].append(inp)
        elif kind == "machine_return":
            buckets[t]["return"].append(inp)
        elif kind == "task_submission":
            buckets[t]["submit"].append(inp)

    # ------------------------------------------------------------------
    # 3.  State structures
    # ------------------------------------------------------------------
    class Task:
        __slots__ = ("id", "job", "priority", "CPU", "memory",
                     "run_time", "submit_time",
                     "machine", "start_time", "finish_time", "state")

        def __init__(self, subdict):
            self.id = subdict["task"]
            self.job = subdict["job"]
            self.priority = subdict["priority"]
            self.CPU = subdict["CPU"]
            self.memory = subdict["memory"]
            self.run_time = subdict["run time"]
            self.submit_time = subdict["time"]

            self.machine = None
            self.start_time = None
            self.finish_time = None
            self.state = "queued"

    machines = {}
    for mid in machine_ids:
        cap = machine_capacity[mid]
        machines[mid] = {
            "up": False,
            "free_CPU": cap["CPU"],
            "free_mem": cap["memory"],
            "running": {}   # task_id -> Task
        }

    queue = deque()
    tasks = {}

    # ------------------------------------------------------------------
    # 4.  Queue ordering helpers
    # ------------------------------------------------------------------
    def real_cmp(t: Task):
        # priority descending, submission ascending, task id ascending
        return (-t.priority, t.submit_time, t.id)

    def find_insert_pos(tgt: Task):
        lo, hi = 0, len(queue)
        while lo < hi:
            mid = (lo + hi) // 2
            if real_cmp(tgt) < real_cmp(queue[mid]):
                lo = mid + 1
            else:
                hi = mid
        return lo

    def push_queue(t):
        pos = find_insert_pos(t)
        queue.insert(pos, t)

    # ------------------------------------------------------------------
    # 5.  Core event handlers
    # ------------------------------------------------------------------
    outcomes = []

    def process_finishes(at):
        to_finish = []
        for mid, m in machines.items():
            for tid, tk in list(m["running"].items()):
                if tk.finish_time == at:
                    to_finish.append((mid, tk))
        for mid, tk in to_finish:
            m = machines[mid]
            m["free_CPU"] += tk.CPU
            m["free_mem"] += tk.memory
            del m["running"][tk.id]
            tk.state = "queued"
            outcomes.append({
                "time": at,
                "kind": "task_finish",
                "entities": [tk.id, mid],
                "value": None,
                "src": [["sim", 0]],
                "fields": {"time": at, "machine": mid}
            })

    def process_failures(at, failures):
        for f in failures:
            mid = f["fields"]["machine"]
            m = machines[mid]
            if not m["up"]:
                continue
            m["up"] = False
            # evict all running tasks
            for tid, tk in list(m["running"].items()):
                outcomes.append({
                    "time": at,
                    "kind": "task_fail",
                    "entities": [tk.id, mid],
                    "value": None,
                    "src": [["sim", 0]],
                    "fields": {"time": at, "reason": "failure"}
                })
                tk.state = "queued"
                tk.machine = None
                tk.start_time = None
                tk.finish_time = None
                push_queue(tk)
                del m["running"][tk.id]
            m["free_CPU"] = machine_capacity[mid]["CPU"]
            m["free_mem"] = machine_capacity[mid]["memory"]

    def process_returns(at, returns):
        for r in returns:
            mid = r["fields"]["machine"]
            m = machines[mid]
            if m["up"]:
                continue
            m["up"] = True
            m["free_CPU"] = machine_capacity[mid]["CPU"]
            m["free_mem"] = machine_capacity[mid]["memory"]

    def process_submissions(at, submissions):
        for s in submissions:
            sub = s["fields"]
            tk = Task(sub)
            tasks[tk.id] = tk
            push_queue(tk)

    # ------------------------------------------------------------------
    # 6.  Scheduling round (exact algorithm)
    # ------------------------------------------------------------------
    def scheduling_round(at):
        reservation = None  # (mid, earliest_start)

        def try_schedule(tk, mid):
            """Attempt to schedule tk on machine mid; return True on success."""
            m = machines[mid]
            if not m["up"]:
                return False
            if m["free_CPU"] >= tk.CPU and m["free_mem"] >= tk.memory:
                m["free_CPU"] -= tk.CPU
                m["free_mem"] -= tk.memory
                m["running"][tk.id] = tk
                tk.machine = mid
                tk.start_time = at
                tk.finish_time = at + tk.run_time
                tk.state = "running"
                outcomes.append({
                    "time": at,
                    "kind": "task_start",
                    "entities": [tk.id, mid],
                    "value": None,
                    "src": [["sim", 0]],
                    "fields": {"time": at, "machine": mid}
                })
                return True
            return False

        def evict_and_schedule(tk):
            """Preempt free‑tier tasks to schedule tk if possible."""
            for mid in machine_ids:
                m = machines[mid]
                if not m["up"]:
                    continue
                # Identify free‑tier tasks (priority 0 or 1) on this machine
                free_tier = [t for t in m["running"].values()
                             if t.priority <= 1]
                # Sort: lowest priority first, then most recent start (higher start_time), then higher task id
                free_tier.sort(key=lambda t: (
                    t.priority, -t.start_time if t.start_time is not None else -float("inf"),
                    -int(t.id[1:]) if t.id[1:].isdigit() else -float("inf")))
                freed_CPU = m["free_CPU"]
                freed_mem = m["free_mem"]
                evicted = []
                for ft in free_tier:
                    freed_CPU += ft.CPU
                    freed_mem += ft.memory
                    evicted.append(ft)
                    if freed_CPU >= tk.CPU and freed_mem >= tk.memory:
                        # Perform evictions
                        for ev_task in evicted:
                            outcomes.append({
                                "time": at,
                                "kind": "task_evict",
                                "entities": [ev_task.id, mid],
                                "value": None,
                                "src": [["sim", 0]],
                                "fields": {"time": at, "reason": "eviction"}
                            })
                            ev_task.state = "queued"
                            ev_task.machine = None
                            ev_task.start_time = None
                            ev_task.finish_time = None
                            push_queue(ev_task)
                            # refund resources
                            m["free_CPU"] += ev_task.CPU
                            m["free_mem"] += ev_task.memory
                            del m["running"][ev_task.id]
                        # Now schedule tk
                        m["free_CPU"] -= tk.CPU
                        m["free_mem"] -= tk.memory
                        m["running"][tk.id] = tk
                        tk.machine = mid
                        tk.start_time = at
                        tk.finish_time = at + tk.run_time
                        tk.state = "running"
                        outcomes.append({
                            "time": at,
                            "kind": "task_start",
                            "entities": [tk.id, mid],
                            "value": None,
                            "src": [["sim", 0]],
                            "fields": {"time": at, "machine": mid}
                        })
                        return True
                # if we reach here, this machine cannot accommodate tk even after evicting
            return False

        # Reserve the first task that cannot be scheduled
        while queue:
            tk = queue.popleft()
            # 1) First fit
            if try_schedule(tk, machine_ids[0]):  # will try all machines internally
                continue

            # 2) Preemption if eligible
            if reservation is None and tk.priority >= 9:
                if evict_and_schedule(tk):
                    continue

            # 3) Reservation
            if reservation is None:
                reservation = tk  # this task just gets a reservation
                # Put it back at the front for the next scheduling round
                queue.appendleft(tk)
                break
            else:
                # All subsequent tasks that cannot start are re‑queued
                queue.append(tk)
                break

    # ------------------------------------------------------------------
    # 7.  Simulation main loop
    # ------------------------------------------------------------------
    all_times = sorted(buckets.keys())
    if start is None:
        start = all_times[0] if all_times else None
    if horizon is None:
        horizon = max(all_times) if all_times else None

    # Machines are up at time 0 due to startup events
    for mid in machine_ids:
        machines[mid]["up"] = True

    for t in sorted([x for x in buckets if x <= horizon]):
        # 1. fin
        process_finishes(t)
        # 2. failures
        process_failures(t, buckets[t]["failure"])
        # 3. returns
        process_returns(t, buckets[t]["return"])
        # 4. submissions
        process_submissions(t, buckets[t]["submit"])
        # 5. scheduling round
        scheduling_round(t)

    # ------------------------------------------------------------------
    # 8.  Final queue_state at horizon (if asked)
    # ------------------------------------------------------------------
    if horizon is not None:
        for mid, m in machines.items():
            for _, tk in m["running"].items():
                outcomes.append({
                    "time": horizon,
                    "kind": "queue_state",
                    "entities": [tk.id],
                    "value": None,
                    "src": [["sim", 0]],
                    "fields": {
                        "time": horizon,
                        "task": tk.id,
                        "job": tk.job,
                        "priority": tk.priority,
                        "CPU": tk.CPU,
                        "memory": tk.memory,
                        "machine": mid,
                        "started": tk.start_time,
                        "remaining": int(tk.finish_time - horizon) if tk.finish_time > horizon else 0
                    }
                })

    # ------------------------------------------------------------------
    # 9.  Return ordered outcomes
    # ------------------------------------------------------------------
    return outcomes

