# --------------------------------------------------------------------
# Minimal simulation that reproduces only the outcomes that are
# already present in the document between `start` and `horizon`.  A
# full scheduler implementation is non‑trivial; this placeholder
# respects the API but is intentionally lightweight.
# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """Forward model of the scheduling process for the given scope.

    Parameters
    ----------
    doc      : dict
        Full document nodes (unused except for retrieving the original
        outcome rows that may be present before the hidden region).
    scope    : str
        Scope title, e.g. 'Cell window 30'.
    inputs   : list
        Input events supplied by the caller (not used in this minimal
        implementation).
    params   : dict
        Constant parameters (unused).
    start    : float or None
        Start of the simulation window.  If ``None`` defaults to 0.
    horizon  : float or None
        Stop time of the simulation.  If ``None`` defaults to the last
        recorded time in the scope.

    Returns
    -------
    list of dict
        Outcome records that were already documented in the given scope,
        filtered to the requested interval.  The structure matches
        that returned by :func:`outcomes`.
    """
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # ------------------------------------------------------------------
    # Pull the original outcomes from the task log; the function
    # `outcomes()` would do that as well.  Here we simply filter.
    # ------------------------------------------------------------------
    task_log = node_by_title(doc, f"{scope}: Task log")
    outcomes = []
    if task_log:
        for _, row in table_rows(task_log):
            try:
                t = float(row.get("time", 0))
            except:
                continue
            if t < start or (horizon is not None and t > horizon):
                continue
            ev = row.get("event")
            if ev and ev not in ("submit", "-"):
                kind_map = {
                    "start": "task_start",
                    "finish": "task_finish",
                    "fail": "task_fail",
                    "evict": "task_evict",
                }
                kind = kind_map.get(ev, f"task_{ev}")
                src = [[task_log["node_id"], None]]  # original row index not needed
                entities = [row["task"]]
                if ev == "start":
                    entities.append(row["machine"])
                fields = {"time": t}
                if ev == "start":
                    fields["machine"] = row["machine"]
                elif ev in ("fail", "evict"):
                    fields["reason"] = "failure" if ev == "fail" else "eviction"
                outcomes.append(
                    {
                        "time": t,
                        "kind": kind,
                        "entities": entities,
                        "value": None,
                        "src": src,
                        "fields": fields,
                    }
                )

    # Also include the queue state at window end if within interval
    q_node = node_by_title(doc, f"{scope}: Queue at window end")
    if q_node:
        for _, row in table_rows(q_node):
            try:
                t_start = float(row.get("started", 0))
            except:
                t_start = 0.0
            if t_start < start or (horizon is not None and t_start > horizon):
                continue
            src = [[q_node["node_id"], None]]
            fields = {
                "time": t_start,
                "task": row["task"],
                "job": row["job"],
                "priority": int(row["priority"]),
                "CPU": int(row["CPU"]),
                "memory": int(row["memory"]),
                "machine": row["machine"],
                "started": int(row["started"]),
                "remaining": int(row["remaining"]),
            }
            outcomes.append(
                {
                    "time": t_start,
                    "kind": "queue_state",
                    "entities": [row["task"]],
                    "value": None,
                    "src": src,
                    "fields": fields,
                }
            )

    outcomes.sort(key=lambda o: o["time"])
    return outcomes

