# --------------------------------------------------------------------
# Simulator ===========================================================
# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """Forward model of the scheduling process for the given scope."""
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # ---------------------------------------------------------------
    # 1. Extract machine information from inputs
    # ---------------------------------------------------------------
    machine_state = {}   # id -> dict with CPU, mem, up, used_cpu, used_mem
    machine_ids = []     # sorted lexicographically

    failure_times = defaultdict(list)   # time -> list of machine_ids
    return_times = defaultdict(list)    # time -> list of machine_ids

    # Keep submission events
    submissions_by_time = defaultdict(list)   # time -> list of task dicts

    # Keep running tasks: task_id -> (machine_id, start_time, run_time)
    running = {}
    # Map machine id -> set of task ids running
    running_on = defaultdict(set)
    # Finish times: time -> set of task ids finishing at that time
    finish_at = defaultdict(set)

    # ------------------------------------------------------------------
    # Parse inputs
    # ------------------------------------------------------------------
    for inp in inputs:
        kind = inp["kind"]
        t = inp["time"]
        if kind == "machine_startup":
            mid = inp["entities"][0]
            machine_state[mid] = {
                "CPU": inp["fields"]["CPU"],
                "memory": inp["fields"]["memory"],
                "up": True,
                "used_CPU": 0,
                "used_mem": 0,
            }
        elif kind == "machine_failure":
            failure_times[t].append(inp["entities"][0])
        elif kind == "machine_return":
            return_times[t].append(inp["entities"][0])
        elif kind == "task_submission":
            task = {
                "id": inp["fields"]["task"],
                "job": inp["fields"]["job"],
                "priority": inp["fields"]["priority"],
                "CPU": inp["fields"]["CPU"],
                "memory": inp["fields"]["memory"],
                "run_time": inp["fields"]["run_time"],
                "submit_time": t,
            }
            submissions_by_time[t].append(task)

    machine_ids = sorted(machine_state.keys())

    # ------------------------------------------------------------------
    # Helper: generate outcome record
    # ------------------------------------------------------------------
    def add_outcome(kind, entities, fields):
        outcomes.append(
            {
                "time": float(fields["time"]),
                "kind": kind,
                "entities": entities,
                "value": None,
                "src": [],
                "fields": fields,
            }
        )

    outcomes = []

    # ------------------------------------------------------------------
    # Main event loop (incremental by integer second for simplicity)
    # ------------------------------------------------------------------
    start_int = int(math.floor(start))
    horizon_int = int(math.ceil(horizon))
    for t in range(start_int, horizon_int + 1):
        # 1. Finishes
        fin_tasks = finish_at.get(t, set())
        for task_id in sorted(fin_tasks):
            mid, start_time, run_time = running.pop(task_id)
            running_on[mid].remove(task_id)
            # free resources
            machine_state[mid]["used_CPU"] -= ES_TASKS[task_id]["CPU"]
            machine_state[mid]["used_mem"] -= ES_TASKS[task_id]["memory"]
            fields = {"time": t, "reason": "none"}
            add_outcome("task_finish", [task_id, mid], fields)
        finish_at.pop(t, None)

        # 2. Failures
        for mid in sorted(failure_times.get(t, [])):
            # Tasks on this machine fail
            failing = sorted(running_on[mid])
            for task_id in failing:
                mid_f, _s, _rt = running.pop(task_id)
                running_on[mid].remove(task_id)
                # Free resources (already counted on removal)
                machine_state[mid]["used_CPU"] -= ES_TASKS[task_id]["CPU"]
                machine_state[mid]["used_mem"] -= ES_TASKS[task_id]["memory"]
                # Put back to queue
                queue.append(ES_TASKS[task_id])
                # Remove scheduled finish if present
                fin_time = _s + _rt
                finish_at[fin_time].discard(task_id)
                # Record fail outcome
                fields = {"time": t, "reason": "failure"}
                add_outcome("task_fail", [task_id, mid], fields)
            machine_state[mid]["up"] = False
            machine_state[mid]["used_CPU"] = 0
            machine_state[mid]["used_mem"] = 0

        # 3. Returns
        for mid in return_times.get(t, []):
            machine_state[mid]["up"] = True
            machine_state[mid]["used_CPU"] = 0
            machine_state[mid]["used_mem"] = 0

        # 4. Submissions
        for task in submissions_by_time.get(t, []):
            queue.append(task)

        # ------------------------------------------------------------
        # 5. Scheduling round
        # ------------------------------------------------------------
        # Sort queue by priority desc, submit_time asc, id asc
        queue.sort(key=lambda x: (-x["priority"], x["submit_time"], x["id"]))
        i = 0
        while i < len(queue):
            task = queue[i]
            # Attempt first fit
            placed = False
            for mid in machine_ids:
                m = machine_state[mid]
                if not m["up"]:
                    continue
                if m["used_CPU"] + task["CPU"] <= m["CPU"] and m["used_mem"] + task["memory"] <= m["memory"]:
                    # schedule
                    m["used_CPU"] += task["CPU"]
                    m["used_mem"] += task["memory"]
                    running[task["id"]] = (mid, t, task["run_time"])
                    running_on[mid].add(task["id"])
                    fin_time = t + task["run_time"]
                    finish_at.setdefault(fin_time, set()).add(task["id"])
                    fields = {"time": t, "machine": mid}
                    add_outcome("task_start", [task["id"], mid], fields)
                    queue.pop(i)
                    placed = True
                    break
            if not placed:
                i += 1

    return outcomes

